sys_variable_value.value:
(function execute(inputs, outputs) {
       var r = new sn_ws.RESTMessageV2('Jira custom field rest msg', 'update jira custom field');
       r.setStringParameterNoEscape('issue_key', inputs.issue_key);

       var payload = {
           fields: {
               customfield_10109: inputs.business_justification,
               customfield_10108: inputs.acceptance_criteria
           }
       };
       r.setRequestBody(JSON.stringify(payload));

       var response = r.execute();
       outputs.status_code1 = response.getStatusCode();
       outputs.response_body = response.getBody();
   })(inputs, outputs);

